"use client";

// Generated by philote from page /swipe. Do not edit.
import { useActionState } from "react";

import type { FormState } from "@/lib/form";

import { NativeSelect, NativeSelectOption } from "@/components/ui/native-select";

import FormField from "@/components/common/form-field";
import SubmitButton from "@/components/common/submit-button";

type Option = { id: string; label: string };

export default function Form({
    action,
    initial,
    options,
}: {
    action: (state: FormState, data: FormData) => Promise<FormState>;
    initial: Record<string, string>;
    options: { horse: Option[]; target: Option[]; };
}) {
    const [state, submit] = useActionState(action, {});
    const values = state.values ?? initial;
    return (
        <form action={submit} className="space-y-6">
            <FormField name="horse" label={"Horse"} issue={state.issues?.horse}>
                <NativeSelect id="horse" name="horse" required defaultValue={values.horse ?? ""} aria-invalid={!!state.issues?.horse} className="w-full">
                    <NativeSelectOption value="">Choose…</NativeSelectOption>
                    {options.horse.map((o) => (
                        <NativeSelectOption key={o.id} value={o.id}>
                            {o.label}
                        </NativeSelectOption>
                    ))}
                </NativeSelect>
            </FormField>
            <FormField name="target" label={"Target"} issue={state.issues?.target}>
                <NativeSelect id="target" name="target" required defaultValue={values.target ?? ""} aria-invalid={!!state.issues?.target} className="w-full">
                    <NativeSelectOption value="">Choose…</NativeSelectOption>
                    {options.target.map((o) => (
                        <NativeSelectOption key={o.id} value={o.id}>
                            {o.label}
                        </NativeSelectOption>
                    ))}
                </NativeSelect>
            </FormField>
            <FormField name="liked" label={"Liked"} issue={state.issues?.liked}>
                <input id="liked" name="liked" type="checkbox" defaultChecked={values.liked === "on"} className="size-4 accent-primary" />
            </FormField>
            {state.error && <p role="alert" className="text-sm text-destructive">{state.error}</p>}
            <SubmitButton>Save</SubmitButton>
        </form>
    );
}
